function withParty(input,count){need(Number.isInteger(count)&&count>=1&&count<=4,'ปาร์ตี้จำลองมีได้ 1–4 คน');const p=copy(input),taken=new Set([p.hero,...p.monsters.map(m=>m.cell)]),allies=[];for(let i=0;i<count-1;i++){const old=p.allies?.[i];let cell=old?.cell;if(!Number.isInteger(cell)||!D.walkable(p.scene.cells[cell])||taken.has(cell)){cell=p.scene.cells.map((c,n)=>({c,n})).filter(x=>D.walkable(x.c)&&!taken.has(x.n)).sort((a,b)=>C.distance(p.scene,D.node(p.hero),D.node(a.n))-C.distance(p.scene,D.node(p.hero),D.node(b.n))||a.n-b.n)[0]?.n;}need(cell!==undefined,'ไม่มีช่องว่างให้เพื่อนร่วมทีม');taken.add(cell);allies.push({cell,job:old?.job||['knight','priest','ranger'][i]});}p.allies=allies;return p;}
